class DataError(ValueError):
    pass


class BookImportError(Exception):
    def __init__(self, error_code, error='Invalid item', **kwargs):
        self.error_code = error_code
        self.error = error
        self.kwargs = kwargs


def parse_meta_headers(edition_builder):
    # parse S3-style http headers
    # we don't yet support augmenting complex fields like author or language
    # string_keys = ['title', 'title_prefix', 'description']

    re_meta = re.compile(r'HTTP_X_ARCHIVE_META(?:\d{2})?_(.*)')
    for k, v in web.ctx.env.items():
        m = re_meta.match(k)
        if m:
            meta_key = m.group(1).lower()
            edition_builder.add(meta_key, v, restrict_keys=False)


def parse_data(data: bytes) -> tuple[dict | None, str | None]:
    """
    Takes POSTed data and determines the format, and returns an Edition record
    suitable for adding to OL.

    :param bytes data: Raw data
    :return: (Edition record, format (rdf|opds|marcxml|json|marc)) or (None, None)
    """
    data = data.strip()
    if b'<?xml' in data[:10]:
        root = etree.fromstring(data)
        if root.tag == '{http://www.w3.org/1999/02/22-rdf-syntax-ns#}RDF':
            edition_builder = import_rdf.parse(root)
            format = 'rdf'
        elif root.tag == '{http://www.w3.org/2005/Atom}entry':
            edition_builder = import_opds.parse(root)
            format = 'opds'
        elif root.tag == '{http://www.loc.gov/MARC21/slim}record':
            if root.tag == '{http://www.loc.gov/MARC21/slim}collection':
                root = root[0]
            rec = MarcXml(root)
            edition = read_edition(rec)
            edition_builder = import_edition_builder.import_edition_builder(
                init_dict=edition
            )
            format = 'marcxml'
        else:
            raise DataError('unrecognized-XML-format')
    elif data.startswith(b'{') and data.endswith(b'}'):
        obj = json.loads(data)
        edition_builder = import_edition_builder.import_edition_builder(init_dict=obj)
        format = 'json'
    elif data[:MARC_LENGTH_POS].isdigit():
        # Marc Binary
        if len(data) < MARC_LENGTH_POS or len(data) != int(data[:MARC_LENGTH_POS]):
            raise DataError('no-marc-record')
        record = MarcBinary(data)
        edition = read_edition(record)
        edition_builder = import_edition_builder.import_edition_builder(
            init_dict=edition
        )
        format = 'marc'
    else:
        raise DataError('unrecognised-import-format')

    parse_meta_headers(edition_builder)
    return edition_builder.get_dict(), format


class importapi:
    """/api/import endpoint for general data formats."""

    def error(self, error_code, error='Invalid item', **kwargs):
        content = {'success': False, 'error_code': error_code, 'error': error}
        content.update(kwargs)
        raise web.HTTPError('400 Bad Request', data=json.dumps(content))

    def POST(self):
        web.header('Content-Type', 'application/json')
        if not can_write():
            raise web.HTTPError('403 Forbidden')

        data = web.data()

        try:
            edition, format = parse_data(data)
            # Validation requires valid publishers and authors.
            # If data unavailable, provide throw-away data which validates
            # We use ["????"] as an override pattern
            if edition.get('publishers') == ["????"]:
                edition.pop('publishers')
            if edition.get('authors') == [{"name": "????"}]:
                edition.pop('authors')
            if edition.get('publish_date') == "????":
                edition.pop('publish_date')

        except DataError as e:
            return self.error(str(e), 'Failed to parse import data')
        except ValidationError as e:
            return self.error('invalid-value', str(e).replace('\n', ': '))

        if not edition:
            return self.error('unknown-error', 'Failed to parse import data')

        try:
            reply = add_book.load(edition)
            # TODO: If any records have been created, return a 201, otherwise 200
            return json.dumps(reply)
        except add_book.RequiredField as e:
            return self.error('missing-required-field', str(e))
        except ClientException as e:
            return self.error('bad-request', **json.loads(e.json))
        except TypeError as e:
            return self.error('type-error', repr(e))
        except Exception as e:
            return self.error('unhandled-exception', repr(e))


def raise_non_book_marc(marc_record, **kwargs):
    details = 'Item rejected'
    # Is the item a serial instead of a monograph?
    marc_leaders = marc_record.leader()
    if marc_leaders[7] == 's':
        raise BookImportError('item-is-serial', details, **kwargs)

    # insider note: follows Archive.org's approach of
    # Item::isMARCXMLforMonograph() which excludes non-books
    if not (marc_leaders[7] == 'm' and marc_leaders[6] == 'a'):
        raise BookImportError('item-not-book', details, **kwargs)


class ia_importapi(importapi):
    """/api/import/ia import endpoint for Archive.org items, requiring an ocaid identifier rather than direct data upload.
    Request Format:

        POST /api/import/ia
        Content-Type: application/json
        Authorization: Basic base64-of-username:password

        {
            "identifier": "<ocaid>",
            "require_marc": "true",
            "bulk_marc": "false"
        }
    """

    @classmethod
    def ia_import(
        cls, identifier: str, require_marc: bool = True, force_import: bool = False
    ) -> str:
        """
        Performs logic to fetch archive.org item + metadata,
        produces a data dict, then loads into Open Library

        :param str identifier: archive.org ocaid
        :param bool require_marc: require archive.org item have MARC record?
        :param bool force_import: force import of this record
        :returns: the data of the imported book or raises  BookImportError
        """
        from_marc_record = False

        # Case 1 - Is this a valid Archive.org item?
        metadata = ia.get_metadata(identifier)
        if not metadata:
            raise BookImportError('invalid-ia-identifier', '%s not found' % identifier)

        # Case 2 - Does the item have an openlibrary field specified?
        # The scan operators search OL before loading the book and add the
        # OL key if a match is found. We can trust them and attach the item
        # to that edition.
        edition_olid = metadata.get('openlibrary_edition') or metadata.get(
            'openlibrary'
        )
        if metadata.get('mediatype') == 'texts' and edition_olid:
            edition_data = cls.get_ia_record(metadata)
            edition_data['openlibrary'] = edition_olid
            edition_data = cls.populate_edition_data(edition_data, identifier)
            return cls.load_book(edition_data)

        # Case 3 - Can the item be loaded into Open Library?
        status = ia.get_item_status(identifier, metadata)
        if status != 'ok' and not force_import:
            raise BookImportError(status, 'Prohibited Item %s' % identifier)

"""Interface to access the database of openlibrary.
"""
import web
import sqlite3
from datetime import datetime
from sqlite3 import IntegrityError
from psycopg2.errors import UniqueViolation
from infogami.utils import stats


@web.memoize
def _get_db():
    return web.database(**web.config.db_parameters)


def get_db():
    """Returns an instance of webpy database object.

    The database object is cached so that one object is used everywhere.
    """
    return _get_db()


class CommonExtras:
    """
    A set of methods used by bookshelves, booknotes, ratings, and observations tables
    """

    @classmethod
    def update_work_id(cls, current_work_id, new_work_id, _test=False):
        """This method allows all instances of a work_id (such as that of a
        redirect) to be updated to a new work_id.
        """
        oldb = get_db()
        t = oldb.transaction()
        rows_changed = 0
        rows_deleted = 0
        failed_deletes = 0

        try:
            rows_changed = oldb.update(
                cls.TABLENAME,
                where="work_id=$work_id",
                work_id=new_work_id,
                vars={"work_id": current_work_id},
            )
        except (UniqueViolation, IntegrityError):
            (
                rows_changed,
                rows_deleted,
                failed_deletes,
            ) = cls.update_work_ids_individually(
                current_work_id, new_work_id, _test=_test
            )
        t.rollback() if _test else t.commit()
        return {
            'rows_changed': rows_changed,
            'rows_deleted': rows_deleted,
            'failed_deletes': failed_deletes,
        }

    @classmethod
    def update_work_ids_individually(cls, current_work_id, new_work_id, _test=False):
        oldb = get_db()
        rows_changed = 0
        rows_deleted = 0
        failed_deletes = 0

        # get records with old work_id
        # `list` used to solve sqlite cursor test
        rows = list(
            oldb.select(
                cls.TABLENAME,
                where="work_id=$work_id",
                vars={"work_id": current_work_id},
            )
        )
        for row in rows:
            where = " AND ".join(
                [f"{k}='{v}'" for k, v in row.items() if k in cls.PRIMARY_KEY]
            )
            try:
                # try to update the row to new_work_id
                t_update = oldb.transaction()
                oldb.query(
                    f"UPDATE {cls.TABLENAME} set work_id={new_work_id} where {where}"
                )
                rows_changed += 1
                t_update.rollback() if _test else t_update.commit()
            except (UniqueViolation, IntegrityError):
                t_delete = oldb.transaction()
                # otherwise, delete row with current_work_id if failed
                oldb.query(f"DELETE FROM {cls.TABLENAME} WHERE {where}")
                rows_deleted += 1
                if _test or not cls.ALLOW_DELETE_ON_CONFLICT:
                    t_delete.rollback()
                else:
                    t_delete.commit()

                if not cls.ALLOW_DELETE_ON_CONFLICT:
                    failed_deletes += 1
                    rows_deleted -= 1
        return rows_changed, rows_deleted, failed_deletes

    @classmethod
    def select_all_by_username(cls, username, _test=False):
        oldb = get_db()
        return list(
            oldb.select(
                cls.TABLENAME, where="username=$username", vars={"username": username}
            )
        )

    @classmethod
    def update_username(cls, username, new_username, _test=False):
        oldb = get_db()
        t = oldb.transaction()

        try:
            rows_changed = oldb.update(
                cls.TABLENAME,
                where="username=$username",
                username=new_username,
                vars={"username": username},
            )
        except (UniqueViolation, IntegrityError):
            # if any of the records would conflict with an exiting
            # record associated with new_username
            pass  # assuming impossible for now, not a great assumption

        t.rollback() if _test else t.commit()
        return rows_changed

    @classmethod
    def delete_all_by_username(cls, username, _test=False):
        oldb = get_db()
        t = oldb.transaction()

        try:
            rows_deleted = oldb.delete(
                cls.TABLENAME, where="username=$username", vars={"username": username}
            )
        except (UniqueViolation, IntegrityError):
            pass

        t.rollback() if _test else t.commit()
        return rows_deleted


def _proxy(method_name):
    """Create a new function that call method with given name on the
    database object.

    The new function also takes care of recording the stats about how
    long it took to execute this query etc.
    """

    def f(*args, **kwargs):
        stats.begin("db", method=method_name, args=list(args), kwargs=kwargs)
        m = getattr(get_db(), method_name)
        result = m(*args, **kwargs)
        stats.end()
        return result

    f.__name__ = method_name
    f.__doc__ = f"Equivalent to get_db().{method_name}(*args, **kwargs)."
    return f


def adapt_datetime_iso(date_time: datetime) -> str:
    """
    Convert a Python datetime.datetime into a timezone-naive ISO 8601 date string.
    >>> adapt_datetime_iso(datetime(2023, 4, 5, 6, 7, 8, 9))
    '2023-04-05 06:07:08.000009'
    """
    return date_time.isoformat(" ")


sqlite3.register_adapter(datetime, adapt_datetime_iso)
query = _proxy("query")

#!/usr/bin/env python

import datetime
import json
import logging
import os
import sys
import time

import scripts._init_path  # Imported for its side effect of setting PYTHONPATH
import web

from openlibrary.api import OLError, OpenLibrary
from openlibrary.config import load_config
from openlibrary.core.ia import get_candidate_ocaids
from openlibrary.core.imports import Batch, ImportItem

logger = logging.getLogger("openlibrary.importer")


@web.memoize
def get_ol(servername=None):
    if os.getenv('LOCAL_DEV'):
        ol = OpenLibrary(base_url="http://localhost:8080")
        ol.login("admin", "admin123")
    else:
        ol = OpenLibrary(base_url=servername)
        ol.autologin()
    return ol


def ol_import_request(item, retries=5, servername=None, require_marc=True):
    """Requests OL to import an item and retries on server errors."""
    # logger uses batch_id:id for item.data identifier if no item.ia_id
    _id = item.ia_id or f"{item.batch_id}:{item.id}"
    logger.info(f"importing {_id}")
    for i in range(retries):
        if i != 0:
            logger.info("sleeping for 5 seconds before next attempt.")
            time.sleep(5)
        try:
            ol = get_ol(servername=servername)
            if item.data:
                return ol.import_data(item.data)
            return ol.import_ocaid(item.ia_id, require_marc=require_marc)
        except OSError as e:
            logger.warning(f"Failed to contact OL server. error={e!r}")
        except OLError as e:
            logger.warning(f"Failed to contact OL server. error={e!r}")
            if e.code < 500:
                return e.text


def do_import(item, servername=None, require_marc=True):
    import os

    logger.info(f"do_import START (pid:{os.getpid()})")
    response = ol_import_request(item, servername=servername, require_marc=require_marc)
    if response and response.startswith('{'):
        d = json.loads(response)
        if d.get('success') and 'edition' in d:
            edition = d['edition']
            logger.info(f"success: {edition['status']} {edition['key']}")
            item.set_status(edition['status'], ol_key=edition['key'])
        else:
            error_code = d.get('error_code', 'unknown-error')
            logger.error(f"failed with error code: {error_code}")
            item.set_status("failed", error=error_code)
    else:
        logger.error(f"failed with internal error: {response}")
